  cf_names.push_back(kFtsStatCfName);

  auto dst_ctx = std::make_shared<RocksdbContext>();
  Status s = dst_ctx->create(
      RocksdbContext::Args{dst_fts_path, cf_names, nullptr, per_cf_merge_ops,
                           /*enable_hash_skiplist=*/true});
