    auto *dst_positions_cf = dst_ctx->get_cf(name + kFtsPositionsSuffix);

    fts::FtsRocksdbReducer reducer;
    auto init_ret = reducer.init(name, dst_ctx.get(), dst_postings_cf,
                                 dst_positions_cf, dst_stat_cf);
